def require_memory_write() -> None:
    if oauth_enabled():
        principal = current_principal()
        if principal is None or WRITE_SCOPE not in principal.scopes:
            raise HTTPException(status_code=403, detail="OAuth access token lacks required scope: memory.write")
    if not memory_write_enabled():
        raise HTTPException(
            status_code=403,
            detail="Memory writes are disabled on this deployment",
        )

def current_user(
    request: Request,
    textech_session: str | None = Cookie(default=None, alias=settings.cookie_name),
    authorization: str | None = Header(default=None),
    x_api_token: str | None = Header(default=None),
) -> dict[str, Any]:
    if authorization and authorization.lower().startswith("bearer "):
        token = authorization[7:].strip()
        user = dbmod.find_user_by_api_token(token)
        if user:
            return attach_authenticated_user(request, user)
    if x_api_token:
        user = dbmod.find_user_by_api_token(x_api_token.strip())
        if user:
            return attach_authenticated_user(request, user)
    if textech_session:
        data = load_session(textech_session)
        if data:
            user = dbmod.get_user_by_id(int(data["uid"]))
            if user:
                return attach_authenticated_user(request, user)
    raise HTTPException(status_code=401, detail="未登录")

def get_anthropic_client(request: Request) -> Any:
    """Compatibility alias while route type hints migrate to LLMProvider."""
    provider = getattr(request.app.state, "llm_provider", None)
    if provider is not None:
        return get_llm_provider(request)
    client = getattr(request.app.state, "anthropic_client", None)
    if client is None:
        raise HTTPException(
            status_code=503,
            detail=(
                "This feature requires a model provider. Configure ANTHROPIC_API_KEY "
                "and LLM_PROVIDER=anthropic, then restart the service."
            ),
        )
    return client

def require_scope(action: str):
    async def _dep(ctx: RequestContext = Depends(get_request_context)) -> RequestContext:
        try:
            authorize(context=ctx, action=action)
        except AuthorizationError as exc:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail={"code": exc.code, "message": str(exc), "action": action},
            ) from exc
        return ctx

    return _dep

def require_admin(credentials: HTTPBasicCredentials = Depends(security)) -> str:
    # Compared as bytes: on str, compare_digest raises TypeError the moment a
    # credential contains a non-ASCII character, so a password with an accent
    # in it would turn every login into a 500 instead of a 401.
    user_ok = secrets.compare_digest(
        credentials.username.encode("utf-8"), settings.admin_username.encode("utf-8")
    )
    pass_ok = secrets.compare_digest(
        credentials.password.encode("utf-8"), settings.admin_password.encode("utf-8")
    )
    if not (user_ok and pass_ok):
        raise HTTPException(status_code=401, detail="Unauthorized", headers={"WWW-Authenticate": "Basic"})
    return credentials.username

def get_session_store() -> SessionStore | None:
    """Return the session store, or None when the database is not configured.

    Constructing the store opens no connection, so this stays cheap enough to
    resolve before the guard has decided whether a request is worth a lookup.
    Tests override this with an in-memory double.
    """
    factory = get_sessionmaker()
    if factory is None:
        return None

    return PostgresSessionStore(factory, get_settings().session_ttl_days)

