def get_current_active_user(user: User = Depends(get_current_user)) -> User:
    """Blocks every endpoint except login/me/change-password until an
    admin-created account's forced password change is done."""
    if user.must_change_password:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN, detail="Password change required"
        )
    return user

def usuario_atual(
    creds: HTTPAuthorizationCredentials | None = Depends(security),
) -> dict:
    if not creds:
        raise HTTPException(status_code=401, detail="Não autenticado")

    try:
        payload = jwt.decode(creds.credentials, SECRET, algorithms=[ALGORITHM])
        user_id = payload["sub"]
    except jwt.PyJWTError:
        raise HTTPException(status_code=401, detail="Token inválido")

    usuario = obter_usuario(user_id)
    if not usuario or not usuario.get("ativo", True):
        raise HTTPException(status_code=401, detail="Usuário não encontrado")
    if not usuario.get("empresa_id"):
        raise HTTPException(status_code=401, detail="Usuário sem empresa vinculada")
    return usuario

