def basic_auth_enabled() -> None:
    """Dependency: returns 404 when AUTH_BASIC_ENABLED is false.

    Used to gate email/password login, registration and password reset.
    OAuth flows must NOT depend on this — they are independent of basic auth.
    """
    if not get_settings().auth_basic_enabled:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Not Found"
        )

def get_current_user(
    request: Request,
    db: Session = Depends(get_db),
) -> User:
    token = request.cookies.get(settings.session_cookie_name)
    claims = _decode(token) if token else None
    if not claims:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": {"code": "not_authenticated", "message": "Login required"}},
        )
    user = db.get(User, UUID(claims["sub"]))
    if user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": {"code": "not_authenticated", "message": "Session user not found"}},
        )
    return user

